from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import serializers, status
import subprocess
import re
import logging

logger = logging.getLogger(__name__)


class DiagnosticSerializer(serializers.Serializer):
    target_host = serializers.CharField(max_length=255)
    check_type = serializers.ChoiceField(choices=['ping', 'dns', 'traceroute'])
    timeout = serializers.IntegerField(default=5, min_value=1, max_value=30)


def sanitize_hostname(hostname):
    """Basic hostname validation - allows IPs and FQDNs"""
    # Allow alphanumeric, dots, hyphens, colons (IPv6)
    pattern = r'^[a-zA-Z0-9\.\-\:]+$'
    if re.match(pattern, hostname):
        return hostname
    return None


class NetworkDiagnosticView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        serializer = DiagnosticSerializer(data=request.data)
        if not serializer.is_valid():
            return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

        target = serializer.validated_data['target_host']
        check_type = serializer.validated_data['check_type']
        timeout = serializer.validated_data['timeout']

        # Validate hostname format
        clean_target = sanitize_hostname(target)
        if not clean_target:
            return Response(
                {'error': 'Invalid hostname format'},
                status=status.HTTP_400_BAD_REQUEST
            )

        try:
            result = self._run_diagnostic(clean_target, check_type, timeout)
            return Response({'output': result, 'target': clean_target})
        except subprocess.TimeoutExpired:
            return Response(
                {'error': 'Diagnostic timed out'},
                status=status.HTTP_408_REQUEST_TIMEOUT
            )
        except Exception as e:
            logger.error(f"Diagnostic failed: {e}")
            return Response(
                {'error': 'Diagnostic execution failed'},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )

    def _run_diagnostic(self, target, check_type, timeout):
        """Execute network diagnostic command"""
        if check_type == 'ping':
            cmd = f"ping -c 4 -W {timeout} {target}"
        elif check_type == 'dns':
            cmd = f"nslookup {target}"
        elif check_type == 'traceroute':
            cmd = f"traceroute -w {timeout} {target}"
        else:
            raise ValueError("Unknown check type")

        # Execute using shell for pipe support in complex diagnostics
        proc = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=timeout + 5
        )
        return proc.stdout + proc.stderr


