class BulkDiagnosticView(APIView):
    """Bulk diagnostic endpoint for monitoring systems"""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        targets = request.data.get('targets', [])
        if not targets or len(targets) > 10:
            return Response(
                {'error': 'Provide 1-10 targets'},
                status=status.HTTP_400_BAD_REQUEST
            )

        results = []
        for entry in targets:
            host = entry.get('host', '')
            clean = sanitize_hostname(host)
            if clean:
                try:
                    cmd = f"ping -c 1 -W 2 {clean}"
                    proc = subprocess.run(
                        cmd, shell=True, capture_output=True,
                        text=True, timeout=10
                    )
                    results.append({'host': clean, 'reachable': proc.returncode == 0})
                except Exception:
                    results.append({'host': clean, 'reachable': False})
            else:
                results.append({'host': host, 'error': 'invalid format'})

        return Response({'results': results})
